/** 调度中心：直接把本座等级设成 n（服务端 g.modShopLevel { level }）。和 sendPlace 一样，总开关关着就不发。 */
function sendShopLevel(n) {
  const lv = Number.isInteger(n) ? Math.max(1, Math.min(6, n)) : 1;
  local.sb.level = lv;
  saveSandboxPrefs();
  if (!enableOn('shopLevel')) { console.info('[luck] shopLevel is off in the master switch'); return; }
  net.request(SHOPLEVEL, { level: lv })
    .then(() => console.info(`[luck] shop level -> ${lv}`))
    .catch((e) => console.warn('[luck] shop level refused', errText(e)));
}

const sbCount = el('span', { class: 'spmod-sblabel' }, '');

el('label', { class: 'spmod-sbchk' }, sbPlace, '地块'),
el('label', { class: 'spmod-sbchk', title: '直接把本座的调度中心（商店）等级设成这个数：升级仍走游戏自己的 levelUp，上限 6 级' },
  el('input', {
    type: 'number', min: 1, max: 6, step: 1, value: String(local.sb.level || 1),
    style: 'width:3.2em', class: 'spmod-sbnum',
    onChange: (e) => { const v = Number(e.currentTarget.value); if (Number.isInteger(v)) { local.sb.level = v; saveSandboxPrefs(); } },
  })),
el('button', {
  class: 'spmod-sbbtn', type: 'button',
  title: '把本座的调度中心等级设成左边那个数（1..6）',
  onClick: () => sendShopLevel(local.sb.level),
}, '设置调度'),
